  gorsel: null,
  secenekler: ["Eski eşyaları yenilerinden üstün tutuyor.", "Yeni forma alınmasına baştan karşı çıkıyor.", "Anılar taşıyan eşyalardan kolay vazgeçemiyor.", "Annesinin kararına büyük öfkeyle tepki veriyor."],
